CREATE TABLE "rekening_toko" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "rekening_toko_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"jenis" varchar(10) NOT NULL,
	"bank" varchar(30) NOT NULL,
	"nomor" varchar(30),
	"atas_nama" varchar(40),
	"nama" varchar(60) NOT NULL,
	"is_default" boolean DEFAULT false NOT NULL,
	"status_aktif" varchar(10) DEFAULT 'AKTIF' NOT NULL,
	"dibuat_pada" timestamp with time zone DEFAULT now() NOT NULL,
	"diubah_pada" timestamp with time zone,
	CONSTRAINT "chk_rekening_jenis" CHECK (jenis in ('TRANSFER','EDC','QRIS')),
	CONSTRAINT "chk_rekening_status" CHECK (status_aktif in ('AKTIF','NONAKTIF'))
);
